INSERT INTO package_questions (id, package_id, question_json, status, order_index) VALUES ('8664fbcd-23ae-49e9-9e10-647d9e4d5d41', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal vantagem do sistema de cultura líquido ''MGIT'' (Mycobacteria Growth Indicator Tube) sobre o meio sólido tradicional?", "options": {"a": "Tempo de detecção muito reduzido (média de 1 a 2 semanas), permitindo um diagnóstico e teste de sensibilidade muito mais rápidos.", "b": "Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Inundação de açúcar na sela túrcica pálida massiva profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "O meio líquido facilita o acesso dos nutrientes e a dispersão do bacilo, acelerando exponencialmente o crescimento. O monitoramento é automatizado através da fluorescência sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Tecnologia microbiológica moderna e viga-mestra na infectologia hospitalar profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "b": "Incorreta. Culturas não matam o bacilo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["MGIT", "Cultura Líquida", "Diagnóstico Rápido", "Microbiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 150), ('85e74fb1-b062-42c7-8746-14270406012c', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "O ''Fator Corda'' (Trehalose Dimicolato) é uma substância presente na parede celular do Mycobacterium tuberculosis. Qual o seu principal papel biológico e como ele é observado em laboratório?", "options": {"a": "Relacionado à virulência do bacilo, causando a formação de agregados bacilares em cadeias serpentinas (cordas) visíveis ao microscopia nas culturas.", "b": "Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Transformação do dente em osso pálido profundo massivo profundo pálida profunda pálida profunda.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "O Fator Corda impede a migração de neutrófilos e estimula a formação de granulomas. A observação de ''formação de cordas'' (serpentine cords) em meios líquidos é um forte indicativo presuntivo de M. tuberculosis em relação a outras micobactérias saprófitas pálida profunda pálida pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Fisiopatologia microbiológica e fator de virulência clássico viga-mestra profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "b": "Incorreta. Faz parte da estrutura do bacilo vivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inespecífico biológico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["Fator Corda", "Virulência", "Parede Celular", "Cordas Serpentinas"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 151), ('1860aa01-8507-466f-bd9d-c5c3b2ca125d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A enzima ''Catalase'' está presente em quase todas as micobactérias. No entanto, o Mycobacterium tuberculosis possui uma característica térmica única em relação a essa enzima. Qual é ela?", "options": {"a": "O MTB perde sua atividade de catalase quando aquecido a 68 graus Celsius por 20 minutos (Catalase termo-labial negativa).", "b": "A catalase do MTB suporta 500 graus de fogo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura súbita de asma pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Apenas excesso de iodo marinho massivo no pulmão pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "Quase todas as micobactérias não-tuberculosas (MNT) possuem catalase termo-estável (permanecem positivas após o aquecimento). A denaturação térmica da catalase do MTB é um teste presuntivo rápido e de baixo custo em laboratórios de identificação sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Bioquímica de identificação sistemática e viga-mestra na diferenciação de bacilos profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida.", "b": "Incorreta. Absurdo termodinâmico biológico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["Catalase", "Identificação", "Termo-labial", "Diferenciação"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 152), ('14616290-7bc9-4eed-8e22-4b9e951bdce4', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A substância ''TCH'' (hidrazida do ácido tiofeno-2-carboxílico) é utilizada em meios de cultura para diferenciar quais micobactérias?", "options": {"a": "Diferenciar M. tuberculosis (Resistente ao TCH) de M. bovis (Sensível ao TCH, não crescendo no meio).", "b": "Troca integral do sangue pelo iodo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura total de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Apenas excesso de açúcar na saliva pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Somente bócio tóxico antigo profundo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}, "answer": "a", "rationale": "O teste de TCH é clássico e específico. O M. bovis é unicamente suscetível a este inibidor, permitindo ao laboratório confirmar a origem zoonótica da infecção (bacilo de gado) sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Teste diferencial microbiológico especializado viga-mestra profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "b": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. Confusão anatômica tireoidiana pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}, "difficulty": "dificil", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["TCH", "M. bovis", "Diferenciação", "Zoonoses"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 153), ('ea5d1b75-8f37-4dfc-8156-d5b499dea834', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A coloração por ''Auramina-Rodamina'' utiliza a propriedade de fluorescência para detectar micobactérias. Qual a principal vantagem desta técnica sobre a coloração tradicional de Ziehl-Neelsen no laboratório clínico?", "options": {"a": "Maior sensibilidade e rapidez, permitindo rastrear o esfregaço em menor magnificação (objetivas de 25x ou 40x), cobrindo uma área maior da lâmina em menos tempo.", "b": "Transformar o bacilo em diamante pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura súbita de miopia pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Apenas iodo marinho massivo no pulmão pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Nenhuma vantagem; o custo inviabiliza o uso em massa pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}, "answer": "a", "rationale": "A fluorescência faz os bacilos brilharem intensamente no campo escuro, facilitando a visualização rápida. Enquanto o ZN exige imersão (100x), a Auramina permite ao técnico detectar bacilos mais raros de forma mais eficiente sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Técnica laboratorial de microscopia e viga-mestra no rastreamento rápido profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "b": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. Em laboratórios de grande volume, a rapidez compensa o custo do microscópio de fluorescência sela túrcica profunda pálida profunda pálida profunda."}, "difficulty": "media", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["Fluorescência", "Auramina", "Diagnóstico", "Microscopia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 154), ('e3ac23f6-4c94-43a9-97b4-fcab694bbf81', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Redução de Nitrato'' a nitrito é um teste fundamental na identificação de micobactérias. Como o M. tuberculosis se comporta neste teste bioquímico?", "options": {"a": "O MTB é fortemente positivo para a redução de nitrato (possui a enzima nitrato-redutase).", "b": "Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Substituição do açúcar por iodo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "Junto com a niacina, a redução de nitrato é o pilar de identificação definitiva do MTB. A detecção dessa enzima permite diferenciar o MTB do complexo M. avium e de várias micobactérias de crescimento rápido sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Bioquímica diagnóstica e viga-mestra na taxonomia bacteriana infalível profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "b": "Incorreta. Bioquímica de metabolismo ativo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.", "e": "Incorreta."}, "difficulty": "facil", "subspecialty": "Microbiologia", "subject": "Tuberculose", "tags": ["Nitrato", "MTB", "Microbiologia", "Metabolismo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 155), ('680b85d7-c3fb-4977-815d